Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.

Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

Ltac fold_b8 :=
  repeat match goal with |- context [bv_unsigned (Z_to_bv 8 ?z)] =>
    let v := eval vm_compute in (bv_unsigned (Z_to_bv 8 z)) in change (bv_unsigned (Z_to_bv 8 z)) with v end.
(* [comment removed for export] *)
Ltac has_var c := match c with context [?x] => is_var x end.
Ltac if_closed :=
  lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
    tryif has_var c then fail else
    (let v := eval vm_compute in c in first [constr_eq v true | constr_eq v false]; change c with v; cbv iota) end.
(* [comment removed for export] *)
Ltac fold_zext := repeat match goal with |- evt _ _ (MS ?r _ _ _ _ _ _) => match r with context [zext 64 ?e] =>
  tryif has_var e then fail else (let v := eval vm_compute in (bv_unsigned (zext 64 e)) in
    replace (zext 64 e) with (Z_to_bv 64 v) by (apply bv_eq; vm_compute; reflexivity)) end end.
(* [comment removed for export] *)
Ltac fold_zlit := repeat match goal with |- evt _ _ (MS ?r _ _ _ _ _ _) => match r with context [Z_to_bv 64 ?e] =>
  tryif first [is_Zlit e | has_var e] then fail else (let v := eval vm_compute in e in change (Z_to_bv 64 e) with (Z_to_bv 64 v)) end end.
Ltac istep := xstep; fold_b8; fold_zext; fold_closed_in_goal; try (first [if_closed | if_true | if_false]).
Ltac isteps_to p := repeat (tryif at_pc p then fail else istep).
(* [comment removed for export] *)
Ltac nsub := match goal with |- evt _ _ (MS ?r _ _ _ _ _ _) =>
  match r with context [Z.sub ?u ?c] => is_Zlit c; let v := eval vm_compute in (- c) in replace (u - c) with (u + v) by lia end end.
Ltac jstep := first [istep | nsub; istep].
Ltac jsteps_to p := repeat (tryif at_pc p then fail else jstep).
Ltac showpc := match goal with |- evt _ _ (MS _ _ ?pc _ _ _ _) => idtac "PC:" pc end.

Definition scommon_entry : Z := 0xb6438.
Notation SCOMMON_DEPTH := 2320%Z (only parsing).   (* [comment removed for export] *)

Section WithRIP.
Hypothesis RIP : rip_stmt.


Lemma scommon_rchk : forall (usp : Z) (ra gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    F fc (m : mem) (lo : Z),
  stk asegs m lo (usp + -2240) -> lo <= usp - 2320 -> kHighShadowEnd + 8 <= lo -> usp < 2^63 ->
  chk_ok m SSCANF_FMT 6 -> m2s_cells m -> icells_sn m -> mem_inv asegs m ->
  evt asegs (fun ms' => exists (m' : mem) (ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word),
      ms' = MS (mkR ra' (Z_to_bv 64 (usp + -2240)) gp tp t0' t1' t2' s0 s1 a0' a1' a2' a3' a4' a5' a6' a7'
                    s2 s3 (Z_to_bv 64 SSCANF_FMT) (Z_to_bv 64 6) s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
               F (Z_to_bv 64 0xb64e4) fc None m' (seg_rom asegs)
      /\ munch [(usp - 2320, usp - 2240)] m m' /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (usp + -2240))
    (MS (mkR ra (Z_to_bv 64 (usp + -2240)) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 5) a1 a2 a3 a4 a5 a6 a7
             s2 s3 (Z_to_bv 64 SSCANF_FMT) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xb6498) fc None m (seg_rom asegs)).
Proof.
