(* [comment removed for export] *)
Lemma scommon_wchk : forall (usp p : Z) (ra gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    F fc (m : mem) (lo : Z),
  stk asegs m lo (usp + -2240) -> lo <= usp - 2320 -> kHighShadowEnd + 8 <= lo -> usp < 2^63 ->
