Lemma rw_cells_reshape : forall (m : mem) A cs cs',
  rw_cells asegs m A cs -> cells_wf cs' -> cells_bytes cs' = cells_bytes cs -> rw_cells asegs m A cs'.
Proof.
ltac2:(KReplay.run1 (kr_t_I_scommon ()) ["WithRIP"] "h01Hh11lh21Ah31Bh41Eh51Rh61Wh72W'h82csh93cs'h:1mh;1np;1p;4p;3p;6p;2g001:j14Tg001_j1=Tg002=j1<Tg003Ej1ATg00Hej1@Tg027Oj49Tg038jj48Tg02L2j15Tg00noj11Tg039dj12Tg03:^j10Tg00T<j37Tg01Chj46Tg000\j6;Tg02Faj4?Tg01h@j2:Tg03;[j2>Tg021kj6CTg03<_j4BTg02O2R0f2R1f1R2f0R3CBp=3g02]M#4#4#4R4#4#4#4#=#<%=4#<R4#A[g02Ojg02QO#@R5P0f3R6P1P2C9g00:QR7P0f4R8P6P1C8%51#19386%21%@4R9%06%0837P0f7R:f6R;P8C9[[P3P0P;f5R<P8C8P7%2<P0P:P;%0<C6f8R<%5;#173:%2;%0:%0<R;579P0f;R7f:R=P<C9[[[P3%2:P0P=f9R:P;C6%5:#1937=%2:%0=%07R=579P0f>R:f=R;P7C8%57R<#193:;%27P0P:P;P=C6P2P9f<R;#0R>P0f?R0P:P3C6X19P6P=P3E;C?g02\nR61:4=%13930:X;6R?P9P>1:43#1930:X19P6%5;P?P11:4>1>;8E;P=P3E;P<1>72ECC?W4W7W5W3W6P2P3O2n2001000000120000000W0P2P3O2n2001000000121000000W0X95W8W2W:o"). Qed.

(* [comment removed for export] *)
Ltac forget_cells FR :=
  apply rw_cells_forget in FR; let j := fresh "junk" in destruct FR as [j FR]; cbn [cells_size csize Nat.add] in FR.
(* [comment removed for export] *)
Ltac reshape_to FR cs := apply (rw_cells_reshape _ _ _ cs) in FR; [| cbn; repeat split; reflexivity| vm_compute; reflexivity].

Notation z8x8 := [Z_to_bv 8 0; Z_to_bv 8 0; Z_to_bv 8 0; Z_to_bv 8 0; Z_to_bv 8 0; Z_to_bv 8 0; Z_to_bv 8 0; Z_to_bv 8 0] (only parsing).

(* [comment removed for export] *)
Lemma scommon_ro :
  ro_bytes_b asegs SSCANF_FMT (map (Z_to_bv 8) SSCANF_FMT_BYTES) = true
  /\ ro_bytes_b asegs 0x255bd (map (Z_to_bv 8) [106; 122; 116; 76; 113; 0]) = true
  /\ ro_bytes_b asegs 0x1e98f (map (Z_to_bv 8) [99; 67; 115; 83; 91; 0]) = true
  /\ ro_bytes_b asegs 0x27c5d (map (Z_to_bv 8) [100; 105; 111; 117; 120; 88; 110; 0]) = true
  /\ ro_bytes_b asegs 0x10780 (map (Z_to_bv 8) [170; 170; 170; 170; 170; 170; 170; 170]) = true.
Proof.
ltac2:(KReplay.run1 (kr_t_I_scommon ()) ["WithRIP"] "p;3p;2p;4p;1g00T<j3BTg00:Qj26Tg00MUj2DTg02Faj4=Tg001:j10Tg001_j1GTg002=j1ETg00<gj1CTg03=Tj4;Tg03>0j3:Tg002`j12Tg00A8j1FTg01CHj37Tg005[j1<Tg02WJR0f0R1g02WjR23Bp=9%01#0p=3%21#0p=4%21#2p=1%01#2p=8%21#<p=@g02OjR3f1R4#<;71p=?f2R5#<%<4=731573p=5%01#<p=AA73419735p=>AB022R51655R4,65R1,651D02R2P5P1P2P5P4P2P5P5P2P2C=C=C=C=g02O2R2g02_2P3g02]MR5#0R4#0R1#0R0#GR6#ER7%C6R6g03>lC;3:#9%35#4#4#4#1#8#1#4#@P3P7P6%25R8#0R9#2R:#0R;#4%28R8#4R<#4%08R8#4R=#0%11#3%08R8#8g02RG%F3R1573R>'?3535C;5:2#9%25#1#8#3#1#3#8#1#@P3P7P6%09R9#0#1%00R0#1%18%24R4#0R8#0#1%44R4#1/?>3535C;5:2#9%35#1#1#4#3#4#1#4#@P3P7P6%29#3%8;%1:R:#2%2=%3<%34%0:/?>353535C;5:2#9%00#1#1#3#3#3#AP3P7P6%28#8#AR8A>8819>889>887>8C;5:2#9'6'6'6'6do"). Qed.

Definition scommon_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp - SCOMMON_DEPTH, bv_unsigned sp)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp).


(* [comment removed for export] *)
Theorem scommon_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (aq p1 p2 : Z) (lo : Z),
  a1 = Z_to_bv 64 2 -> a2 = Z_to_bv 64 SSCANF_FMT -> a3 = Z_to_bv 64 aq ->
  rw_cells asegs m aq [C8 (Z_to_bv 64 p1); C8 (Z_to_bv 64 p2)] -> bv_unsigned sp <= aq -> aq + 16 <= 2^47 ->
  chk_ok m SSCANF_FMT 6 -> chk_ok m p1 4 -> chk_ok m p2 4 ->
  0 <= p1 -> p1 + 4 <= 2^47 -> p1 mod 8 = 0 -> 0 <= p2 -> p2 + 4 <= 2^47 -> p2 mod 8 = 0 ->
  m2s_cells m -> icells_sn m ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - SCOMMON_DEPTH -> kHighShadowEnd + 8 <= lo -> (bv_unsigned sp) mod 16 = 0 ->
  mem_inv asegs m ->
  evt asegs (scommon_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
